function show_name(uuid) {
    for (var i = 0; i < nameuser.length; i++) {
        if (uuid == nameuser[i].uuid) {
            return nameuser[i].name;
        }
    }
    return "";
}
// ฟังก์ชันเพื่อค้นหา link
function show_link(uuid) {
    for (var i = 0; i < nameuser.length; i++) {
        if (uuid == nameuser[i].uuid) {
            return nameuser[i].link || "N/A"; // หาก link ไม่มีค่า ให้แสดงเป็น "N/A"
        }
    }
    return "N/A";
}

