var data = msg.payload;
var error_text = ""; // ตัวแปรสำหรับเก็บข้อความของข้อผิดพลาด
var time_now = Date.now();
var lasttime_error = flow.get(uidKey);
if (!lasttime_error) {
    lasttime_error = 0;
}
var text_line = "";
msg.check_send_noti = 0;

// ตรวจสอบข้อมูลที่อยู่ใน nameuser เท่านั้น
var isValidUUID = nameuser.some(function (item) {
    return item.uuid === uid[1];
});



// ตรวจสอบว่าข้อมูล data[13] ไม่เท่ากับ 0 และเวลาผ่านไปหลังจากข้อผิดพลาดครั้งก่อนหน้ามากกว่าหรือเท่ากับ 10 นาที หรือไม่มีเวลาของข้อผิดพลาดก่อนหน้า ให้ทำการส่งข้อความ
if (isValidUUID && data[13] != 0 && (time_now - lasttime_error >= 10 * 60 * 1000)) {
    if (data[0] == 100 && (data[1] != 61 && data[1] != 62 && data[1] != 63)) {
        if (data[13] == 1) {
            error_text = "ARC";
        } else if (data[13] == 2) {
            error_text = "LEAKAGE CURRENT";
        } else if (data[13] == 4) {
            error_text = "UNDER VOLTAGE";
        } else if (data[13] == 8) {
            error_text = "OVER VOLTAGE";
        } else if (data[13] == 16) {
            error_text = "OVER CURRENT";
        } else if (data[13] == 32) {
            error_text = "SHORT CIRCUIT";
        } else if (data[13] == 64) {
            error_text = "OVER TEMP";
        } else if (data[13] == 128) {
            error_text = "EQ";
        } else if (data[0] == 100 && data[13] == 67) {
            error_text = "Send Order Arc Alarm";
        } else if (data[0] == 100 && data[13] == 64) {
            error_text = "Send Order OC Alarm";
        } else if (data[0] == 100 && data[13] == 65) {
            error_text = "Send Order SC Alarm";
        } else if (data[0] == 100 && data[13] == 14) {
            error_text = "Fault trip : " + data[13] + " , " + data[14];
        }

        if (error_text !== "" && data[1] != 67) {
            // สร้างข้อความแจ้งเตือน
            text_line = "Fault Situation at " + "\nUID : " + uid[1] + "\nPROJECT : SINGAPORE\nNAME : " + show_name(uid[1]) + "\nError : " + error_text + "\nLINK : " + show_link(uid[1]);
            msg.check_send_noti = 1;
            //datalog
            var datalog = {}
            datalog.uid = uid[1]
            datalog.project = "SINGAPORE"
            datalog.name = show_name(uid[1])
            datalog.error = error_text
            msg.datalog = datalog
            // ส่งข้อความ text_line
            msg.payload = { "message": text_line };
            flow.set(uidKey, Date.now());
        }
    }
}

